		case PT_PR_IS_VARIADIC: { bool r; if (UNEXPECTED(!pgen::PhpParameterReflection::m_isVariadic(parameter, &r))) return zv::Val(); return zv::Val::boolean(r); }
		case PT_PR_GET_DEFAULT_VALUE: { zv::Val r; if (UNEXPECTED(!pgen::PhpParameterReflection::m_getDefaultValue(parameter, r.raw()))) return zv::Val(); return r; }
		case PT_PR_GET_PHPDOC_TYPE: { zv::Val r; if (UNEXPECTED(!pgen::PhpParameterReflection::m_getPhpDocType(parameter, r.raw()))) return zv::Val(); return r; }
		case PT_PR_HAS_NATIVE_TYPE: { bool r; if (UNEXPECTED(!pgen::PhpParameterReflection::m_hasNativeType(parameter, &r))) return zv::Val(); return zv::Val::boolean(r); }
		case PT_PR_GET_NATIVE_TYPE: { zv::Val r; if (UNEXPECTED(!pgen::PhpParameterReflection::m_getNativeType(parameter, r.raw()))) return zv::Val(); return r; }
		case PT_PR_GET_OUT_TYPE: { zv::Val r; if (UNEXPECTED(!pgen::PhpParameterReflection::m_getOutType(parameter, r.raw()))) return zv::Val(); return r; }
		case PT_PR_IS_IMMEDIATELY_INVOKED_CALLABLE: { zv::Val r; if (UNEXPECTED(!pgen::PhpParameterReflection::m_isImmediatelyInvokedCallable(parameter, r.raw()))) return zv::Val(); return r; }
